    [WinFormsFact]
    public void Application_Exit_MDIContainer_CloseAllFormsInOrder()
    {
        using RemoteInvokeHandle invokerHandle = RemoteExecutor.Invoke(() =>
        {
            List<(string Form, string Event)> events = new();

            using Form mdiParent = new()
            {
                IsMdiContainer = true,
                Name = "MdiParent"
            };
            using Form mdiChild1 = new()
            {
                MdiParent = mdiParent,
                Name = "MdiChild1"
            };
            using Form mdiChild2 = new()
            {
                MdiParent = mdiParent,
                Name = "MdiChild2"
            };

            mdiParent.FormClosing += (s, e) => events.Add(((Form)s!).Name, "FormClosing");
            mdiParent.FormClosed += (s, e) => events.Add(((Form)s!).Name, "FormClosed");
            mdiChild1.FormClosing += (s, e) => events.Add(((Form)s!).Name, "FormClosing");
            mdiChild1.FormClosed += (s, e) => events.Add(((Form)s!).Name, "FormClosed");
            mdiChild2.FormClosing += (s, e) => events.Add(((Form)s!).Name, "FormClosing");
            mdiChild2.FormClosed += (s, e) => events.Add(((Form)s!).Name, "FormClosed");

            mdiParent.Show();
            mdiChild1.Show();
            mdiChild2.Show();

            Assert.Equal(3, Application.OpenForms.Count);

            Application.Exit();

            Assert.Equal(0, Application.OpenForms.Count);

            // MDI children must be closed before their MDI parent. Verify the first
            // occurrence of each event is in the correct order.
            int parentClosing = events.FindIndex(@event => @event.Form == "MdiParent" && @event.Event == "FormClosing");
            int parentClosed = events.FindIndex(@event => @event.Form == "MdiParent" && @event.Event == "FormClosed");
            Assert.True(events.FindIndex(@event => @event.Form == "MdiChild1" && @event.Event == "FormClosing") < parentClosing);
            Assert.True(events.FindIndex(@event => @event.Form == "MdiChild2" && @event.Event == "FormClosing") < parentClosing);
            Assert.True(events.FindIndex(@event => @event.Form == "MdiChild1" && @event.Event == "FormClosed") < parentClosed);
            Assert.True(events.FindIndex(@event => @event.Form == "MdiChild2" && @event.Event == "FormClosed") < parentClosed);
        });

        Assert.Equal(RemoteExecutor.SuccessExitCode, invokerHandle.ExitCode);
    }

