            bool newFormClosedRaised = false;

            try
            {
                using Form form = new();
                form.FormClosing += (s, e) =>
                {
                    if (newForm is null)
                    {
                        newForm = new Form();
                        newForm.FormClosing += (s2, e2) => newFormClosingRaised = true;
                        newForm.FormClosed += (s2, e2) => newFormClosedRaised = true;
                        newForm.Show();
                    }
                };

                form.Show();
                Assert.Equal(1, Application.OpenForms.Count);

                Application.Exit();

                Assert.Equal(0, Application.OpenForms.Count);
                Assert.True(newFormClosingRaised);
                Assert.True(newFormClosedRaised);
            }
            finally
            {
                newForm?.Dispose();
            }
        });

        Assert.Equal(RemoteExecutor.SuccessExitCode, invokerHandle.ExitCode);
    }

