internal class WeakRefCollection<T> : IList<T>,
    IReadOnlyList<T> where T : class
{
    private readonly List<WeakRefObject> _innerList;
    private int _refCheckThreshold = 0x7fffffff;

    public T? this[int index]
    {
        get => _innerList[index] is WeakRefObject weakRef && weakRef.IsAlive
            ? weakRef.Target
            : null;
        set => _innerList[index] = CreateWeakRefObject(value);
    }

    public int Count => _innerList.Count;

    public int RefCheckThreshold
    {
        get => _refCheckThreshold;
        set => _refCheckThreshold = value;
    }

    public void ScavengeReferences()
    {
        int currentIndex = 0;
        int currentCount = Count;
        for (int i = 0; i < currentCount; i++)
        {
            WeakRefObject? item = _innerList[currentIndex];
            if (item is null || item.Target is null)
            {
                _innerList.RemoveAt(currentIndex);
            }
            else
            {
                currentIndex++;
            }
        }
    }

    public override bool Equals(object? obj)
    {
        if (obj is not WeakRefCollection<T> other || Count != other.Count)
        {
            return false;
        }

        for (int i = 0; i < Count; i++)
        {
            WeakRefObject? item = _innerList[i];
            if (item != other._innerList[i])
            {
                if (item is null || !item.Equals(other._innerList[i]))
                {
                    return false;
                }
            }
        }

        return true;
    }

    public override int GetHashCode()
    {
        HashCode hash = default;
        foreach (WeakRefObject? o in _innerList)
        {
            hash.Add(o);
        }
        return hash.ToHashCode();
    }

    private static WeakRefObject? CreateWeakRefObject(T? value)
    {
        if (value is null)
        {
            return null;
        }
        return new WeakRefObject(value);
    }

    public void Clear()
    {
        for (int i = 0; i < _innerList.Count; i++)
        {
            _innerList[i] = null;
        }
    }

    public bool Contains(T? item) => IndexOf(item) >= 0;

    public bool Remove(T? value)
    {
        WeakRefObject? weakRef = CreateWeakRefObject(value);
        int index = _innerList.IndexOf(weakRef);
        if (index >= 0)
        {
            _innerList.RemoveAt(index);
            return true;
        }
        return false;
    }

    public int IndexOf(T? value) => _innerList.IndexOf(CreateWeakRefObject(value));

    public void Insert(int index, T? value) => _innerList.Insert(index, CreateWeakRefObject(value));

    public int Add(T? value)
    {
        if (Count > _refCheckThreshold)
        {
            ScavengeReferences();
        }

        _innerList.Add(CreateWeakRefObject(value));

        int index = _innerList.Count - 1;
        return index;
    }

    public void RemoveAt(int index) => _innerList.RemoveAt(index);

    public void CopyTo(T[] array, int index)
    {
        for (int i = index; i < array.Length; i++)
        {
            array[i] = this[i - index];
        }
    }

