            if (value is null)
            {
                return;
            }

            int hash = value.GetHashCode();

            for (int idx = 0; idx < InnerList.Count; idx++)
            {
                if (InnerList[idx] is not null && InnerList[idx]!.GetHashCode() == hash)
                {
                    RemoveAt(idx);
                    return;
                }
            }
        }

