using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows.Forms;

// Mimics ToolStripManager-style usage patterns against a typed WeakRefCollection<T>.

namespace Consumer
{
    public sealed class DummyStrip
    {
        public string Name { get; set; } = "";
    }

    public sealed class DummyPanel
    {
        public string Name { get; set; } = "";
    }

    public sealed class ToolStripManager
    {
        [ThreadStatic]
        private static WeakRefCollection<DummyStrip>? t_toolStripWeakArrayList;

        [ThreadStatic]
        private static WeakRefCollection<DummyPanel>? t_toolStripPanelWeakArrayList;

        internal static WeakRefCollection<DummyStrip> ToolStrips
            => t_toolStripWeakArrayList ??= new WeakRefCollection<DummyStrip>();

        internal static WeakRefCollection<DummyPanel> ToolStripPanels
            => t_toolStripPanelWeakArrayList ??= new WeakRefCollection<DummyPanel>();

        internal static List<DummyStrip> FindByName(string name)
        {
            List<DummyStrip> result = new();
            for (int i = 0; i < ToolStrips.Count; i++)
            {
                if (ToolStrips[i] is DummyStrip strip && string.Equals(strip.Name, name, StringComparison.Ordinal))
                {
                    result.Add(strip);
                }
            }

            return result;
        }

        internal static DummyStrip? FindMergeable(ContainerControl? container)
        {
            for (int i = 0; i < ToolStrips.Count; i++)
            {
                DummyStrip? candidate = ToolStrips[i];
                if (candidate is not null && candidate.Name.Length > 0)
                {
                    return candidate;
                }
            }

            return null;
        }

        internal static int FindNextIndex(DummyStrip start, bool forward)
        {
            int index = ToolStrips.IndexOf(start);
            int totalCount = ToolStrips.Count;
            for (int i = 0; i < totalCount; i++)
            {
                index = forward ? (index + 1) % totalCount : (index + totalCount - 1) % totalCount;
                if (ToolStrips[index] is not DummyStrip toolStrip || toolStrip == start)
                {
                    continue;
                }

                return index;
            }

            return -1;
        }

        internal static DummyPanel? PanelFromPoint(int x, int y)
        {
            if (t_toolStripPanelWeakArrayList is not null)
            {
                for (int i = 0; i < t_toolStripPanelWeakArrayList.Count; i++)
                {
                    if (t_toolStripPanelWeakArrayList[i] is DummyPanel panel && panel.Name.Length > 0)
                    {
                        return panel;
                    }
                }
            }

            return null;
        }
    }

    public class DummyStripView
    {
        public DummyStripView() => ToolStripManager.ToolStrips.Add(this);
    }

    public class DummyPanelView
    {
        public DummyPanelView() => ToolStripManager.ToolStripPanels.Add(this);
    }
}

namespace System.Drawing.Internal
{
    // Mimics DeviceContexts-style usage (System.Drawing.Internal namespace + using System.Windows.Forms).
    public sealed class DeviceContext
    {
    }

    public static class DeviceContexts
    {
        [ThreadStatic]
        private static WeakRefCollection<DeviceContext>? t_activeDeviceContexts;

        internal static void AddDeviceContext(DeviceContext dc)
        {
            WeakRefCollection<DeviceContext> wrc = t_activeDeviceContexts ??= new WeakRefCollection<DeviceContext>
            {
                RefCheckThreshold = 20
            };

            wrc.Contains(dc);
            wrc.Add(dc);
        }

        internal static void RemoveDeviceContext(DeviceContext dc)
        {
            t_activeDeviceContexts?.RemoveByHashCode(dc);
        }
    }
}

