using System;
using System.Collections.Generic;

class Harness
{
    const int OneHundredPercentLogicalDpi = 96;
    const int LogicalSmallIconSize = 16; // SM_CXSMICON / SM_CYSMICON at 96 DPI
    const int LogicalLargeIconSize = 32; // SM_CXICON / SM_CYICON at 96 DPI

    static int ScaleToDpi(int logicalValue, int dpi)
    {
        if (dpi == OneHundredPercentLogicalDpi)
            return logicalValue;
        double scalingFactor = dpi / (double)OneHundredPercentLogicalDpi;
        return (int)Math.Round(scalingFactor * logicalValue);
    }

    // Models GetSystemMetrics(SM_CX*) for a DPI-aware process: physical pixels at the given DPI.
    static int PhysicalMetric(int logicalAt96, int dpi) => ScaleToDpi(logicalAt96, dpi);

    // Old path: ScaleHelper.GetIconResourceAsBitmap(type, resource, dpi)
    //   -> ScaleToDpi(SystemIconSize, dpi) where SystemIconSize is GetSystemMetrics(SM_CXICON) (physical)
    static int OldRequestedSize(int dpi) => ScaleToDpi(PhysicalMetric(LogicalLargeIconSize, dpi), dpi);

    // New path: ScaleHelper.GetIconResourceAsSmallImage(type, resource, dpi)
    //   -> ScaleToDpi(SmallSystemIconSize, dpi) where SmallSystemIconSize is
    //      GetSystemMetricsForDpi(SM_CXSMICON, 96) (logical, DPI-independent)
    static int NewRequestedSize(int dpi) => ScaleToDpi(LogicalSmallIconSize, dpi);

    static int Score(string name, bool condition)
    {
        Console.WriteLine($"{(condition ? "PASS" : "FAIL")} {name}");
        return condition ? 1 : 0;
    }

    static int Main()
    {
        int checks = 0;

        // Single-scaled correct target sizes for the 16x16 "down"/"up" icons.
        foreach (var (dpi, expected) in new[] { (96, 16), (144, 24), (192, 32), (120, 20) })
        {
            checks += Score($"New size at {dpi} DPI == {expected}px", NewRequestedSize(dpi) == expected);
        }

        // The old path produced double-scaled (quadratic) sizes at higher DPI.
        checks += Score("Old path at 96 DPI renders 2x the small icon (32px)", OldRequestedSize(96) == 32);
        checks += Score("Old path at 192 DPI double-scales (128px for a 16px icon)", OldRequestedSize(192) == 128);
        checks += Score("Old path double scales: 16 * (dpi/96)^2", OldRequestedSize(192) == (int)Math.Round(16 * Math.Pow(192.0 / 96, 2)));

        // New path never scales twice.
        checks += Score("New path at 192 DPI is 32px (scaled once)", NewRequestedSize(192) == 32);
        checks += Score("New size == ScaleToDpi(LogicalSmallIconSize, dpi) at 144", NewRequestedSize(144) == ScaleToDpi(LogicalSmallIconSize, 144));

        // New path is DPI-ratio linear: new(2d)/new(d) == 2 for whole-ratio DPI steps.
        checks += Score("New path is linear in DPI (192/96 == 2)", (double)NewRequestedSize(192) / NewRequestedSize(96) == 2.0);
        checks += Score("Old path is quadratic in DPI (192/96 == 4)", (double)OldRequestedSize(192) / OldRequestedSize(96) == 4.0);

        // GetSystemMetricsForDpi(SM_CXSMICON, 96) is DPI-independent (logical).
        checks += Score("Logical small icon metric is constant across DPI",
            PhysicalMetric(LogicalSmallIconSize, 96) == LogicalSmallIconSize
            && ScaleToDpi(LogicalSmallIconSize, 96) == LogicalSmallIconSize);

        Console.WriteLine($"\n{checks}/18 checks passed");
        return checks == 18 ? 0 : 1;
    }
}

