namespace System.Windows.Forms
{
    internal readonly struct Size
    {
        public Size(int w, int h) { Width = w; Height = h; }
        public int Width { get; }
        public int Height { get; }
        public static readonly Size Empty = new(0, 0);
        public bool IsEmpty => Width == 0 && Height == 0;
    }

    internal enum SYSTEM_METRICS_INDEX
    {
        SM_CXICON, SM_CYICON, SM_CXSMICON, SM_CYSMICON
    }

    internal static class PInvoke
    {
        public static int GetSystemMetrics(SYSTEM_METRICS_INDEX i) => i switch
        {
            SYSTEM_METRICS_INDEX.SM_CXICON or SYSTEM_METRICS_INDEX.SM_CYICON => 32,
            _ => 16
        };

        // Mirrors Windows.Win32.PInvoke.GetCurrentSystemMetrics: for Win10 1607+ this is
        // GetSystemMetricsForDpi(nIndex, dpi), so requesting 96 yields the logical (96 DPI) value.
        public static int GetCurrentSystemMetrics(SYSTEM_METRICS_INDEX i, uint dpi)
            => dpi == 96 ? (i == SYSTEM_METRICS_INDEX.SM_CXSMICON || i == SYSTEM_METRICS_INDEX.SM_CYSMICON ? 16 : 32) : GetSystemMetrics(i);
    }

    internal static partial class ScaleHelper
    {
        internal const int OneHundredPercentLogicalDpi = 96;

        internal static int ScaleToDpi(int logicalValue, int dpi)
        {
            if (dpi == OneHundredPercentLogicalDpi) return logicalValue;
            double scalingFactor = dpi / (double)OneHundredPercentLogicalDpi;
            return (int)Math.Round(scalingFactor * logicalValue);
        }

        internal static Size ScaleToDpi(Size logicalSize, int dpi)
            => dpi == OneHundredPercentLogicalDpi
                ? logicalSize
                : new(ScaleToDpi(logicalSize.Width, dpi), ScaleToDpi(logicalSize.Height, dpi));

        internal static Size SystemIconSize => new(
            PInvoke.GetSystemMetrics(SYSTEM_METRICS_INDEX.SM_CXICON),
            PInvoke.GetSystemMetrics(SYSTEM_METRICS_INDEX.SM_CYICON));

        // --- new members under test ---
        internal static Size SmallSystemIconSize => new(
            PInvoke.GetCurrentSystemMetrics(SYSTEM_METRICS_INDEX.SM_CXSMICON, (uint)OneHundredPercentLogicalDpi),
            PInvoke.GetCurrentSystemMetrics(SYSTEM_METRICS_INDEX.SM_CYSMICON, (uint)OneHundredPercentLogicalDpi));

        internal static Bitmap GetIconResourceAsSmallImage(Type type, string resource, int dpi)
            => GetIconResourceAsBitmap(type, resource, ScaleToDpi(SmallSystemIconSize, dpi));
        // --- end new members ---

        internal static Bitmap GetIconResourceAsBitmap(Type type, string resource, int dpi)
            => GetIconResourceAsBitmap(type, resource, ScaleToDpi(SystemIconSize, dpi));

        internal static Bitmap GetIconResourceAsBitmap(Type type, string resource, Size size)
            => new Bitmap(size);
    }

    // Stand-in to allow the internal static class to be instantiated as return type.
    internal sealed class Bitmap
    {
        public Size Size { get; }
        public Bitmap(Size size) => Size = size;
        public int Width => Size.Width;
        public int Height => Size.Height;
    }

