            p += Check(SmallIconAtScale(120).Width == 20, "small 20 @120");
            // 96-DPI metric independent of awareness dpi query
            p += Check(ScaleHelper.SmallSystemIconSize.Width == 16, "SmallSystemIconSize.Width == 16");
            p += Check(ScaleHelper.SmallSystemIconSize.Height == 16, "SmallSystemIconSize.Height == 16");
            return p;

            static Bitmap SmallIconAtScale(int dpi) => ScaleHelper.GetIconResourceAsSmallImage(typeof(object), "res", dpi);
        }

        static int Check(bool cond, string name)
        {
            Console.WriteLine($"{(cond ? "PASS" : "FAIL")} {name}");
            return cond ? 1 : 0;
        }
    }

    internal static class Program
    {
        internal static void Main() => Console.WriteLine($"{Runner.Run()}/7 checks passed");
    }
