using System;
using System.Linq;

enum CheckState
{
    Unchecked,
    Checked,
    Indeterminate,
}

sealed class CheckBox
{
    private CheckState _checkState;
    public bool ThreeState { get; set; }

    public bool Checked
    {
        get => _checkState != CheckState.Unchecked;
        set => CheckState = value ? CheckState.Checked : CheckState.Unchecked;
    }

    public CheckState CheckState
    {
        get => _checkState;
        set
        {
            if (!Enum.IsDefined(typeof(CheckState), value))
                throw new ArgumentOutOfRangeException(nameof(value));
            _checkState = value;
        }
    }
}

sealed class AccessibleObject
{
    private readonly CheckBox _owner;

    public AccessibleObject(CheckBox owner) => _owner = owner;

    // Mirrors the exact overridden members from CheckBox.CheckBoxAccessibleObject.
    public string Value => _owner.ThreeState
        ? _owner.CheckState.ToString()
        : _owner.Checked.ToString();

    public void SetValue(string? newValue)
    {
        if (_owner.ThreeState)
        {
            _owner.CheckState = newValue switch
            {
                string value when value.Equals(CheckState.Checked.ToString(), StringComparison.OrdinalIgnoreCase) => CheckState.Checked,
                string value when value.Equals(CheckState.Unchecked.ToString(), StringComparison.OrdinalIgnoreCase) => CheckState.Unchecked,
                string value when value.Equals(CheckState.Indeterminate.ToString(), StringComparison.OrdinalIgnoreCase) => CheckState.Indeterminate,
                _ => throw new ArgumentException(string.Format("InvalidArgument=Value of '{1}' is not valid for '{0}'.", nameof(newValue), newValue), nameof(newValue))
            };
        }
        else
        {
            _owner.Checked = newValue switch
            {
                string value when value.Equals(bool.TrueString, StringComparison.OrdinalIgnoreCase) => true,
                string value when value.Equals(bool.FalseString, StringComparison.OrdinalIgnoreCase) => false,
                _ => throw new ArgumentException(string.Format("InvalidArgument=Value of '{1}' is not valid for '{0}'.", nameof(newValue), newValue), nameof(newValue))
            };
        }
    }
}

static class Program
{
    static int _passed;
    static int _failed;

    static void Check(bool condition, string name)
    {
        if (condition) { _passed++; }
        else { _failed++; Console.WriteLine($"FAIL: {name}"); }
    }

    static int Main()
    {
        // Value getter, non-ThreeState.
        AccessibleObject a = new(new CheckBox());
        Check(a.Value == "False", "non-three default value is False");
        a.SetValue("True");
        Check(a.Value == "True", "non-three checked value is True");
        a.SetValue("false");
        Check(a.Value == "False", "case-insensitive 'false' sets False");

        // Checked vs CheckState consistency for non-ThreeState.
        CheckBox cb = new() { CheckState = CheckState.Checked };
        AccessibleObject b = new(cb);
        Check(b.Value == "True", "non-three Checked => True");
        cb.CheckState = CheckState.Indeterminate;
        Check(b.Value == "True", "non-three Indeterminate => Checked==true => True");

        // Value getter, ThreeState.
        CheckBox cb3 = new() { ThreeState = true, CheckState = CheckState.Checked };
        AccessibleObject c = new(cb3);
        Check(c.Value == "Checked", "three Checked => Checked");
        cb3.CheckState = CheckState.Unchecked;
        Check(c.Value == "Unchecked", "three Unchecked => Unchecked");
        cb3.CheckState = CheckState.Indeterminate;
        Check(c.Value == "Indeterminate", "three Indeterminate => Indeterminate");

        // SetValue non-ThreeState successes + case-insensitive.
        CheckBox cbSet = new();
        AccessibleObject d = new(cbSet);
        d.SetValue("True");
        Check(cbSet.Checked, "SetValue True checks");
        d.SetValue("FALSE");
        Check(!cbSet.Checked, "SetValue FALSE unchecks");
        cbSet.ThreeState = true;
        d.SetValue("Checked");
        Check(cbSet.CheckState == CheckState.Checked, "SetValue Checked");
        d.SetValue("indeterminate");
        Check(cbSet.CheckState == CheckState.Indeterminate, "SetValue indeterminate");
        d.SetValue("UNCHECKED");
        Check(cbSet.CheckState == CheckState.Unchecked, "SetValue UNCHECKED");

        // Invalid values throw ArgumentException in both modes.
        CheckBox cbInv = new();
        AccessibleObject e = new(cbInv);
        bool threw1 = false;
        try { e.SetValue("invalid"); } catch (ArgumentException ex) when (ex.ParamName == "newValue") { threw1 = true; }
        Check(threw1, "invalid non-three throws ArgumentException with paramName");
        Check(cbInv.Checked == false, "invalid value did not change state");

        cbInv.ThreeState = true;
        bool threw2 = false;
        try { e.SetValue("maybe"); } catch (ArgumentException) { threw2 = true; }
        Check(threw2, "invalid three throws ArgumentException");

        bool threw3 = false;
        try { e.SetValue(""); } catch (ArgumentException) { threw3 = true; }
        Check(threw3, "empty string throws ArgumentException");

        bool threw4 = false;
        try { e.SetValue(null); } catch (ArgumentException) { threw4 = true; }
        Check(threw4, "null throws ArgumentException");

        // Round-trip write/read through Value and SetValue.
        CheckBox cbRT = new() { ThreeState = true };
        AccessibleObject f = new(cbRT);
        foreach (string s in new[] { "Indeterminate", "checked", "unchecked" })
        {
            f.SetValue(s);
            Check(f.Value == cbRT.CheckState.ToString(), $"round-trip {s} -> {f.Value}");
        }

        Console.WriteLine($"PASS: {_passed}, FAIL: {_failed}");
        return _failed == 0 ? 0 : 1;
    }
}

