```csharp
private byte[] Compress(ReadOnlySpan<byte> frameData, int frameHeight)
{
    using MemoryStream memoryStream = new();
    using (var zlibStream = new ZLibStream(memoryStream, CompressionLevel.Optimal, leaveOpen: true))
    using (zlibStream.EnterWriteMode())
    {
        // write filter byte + row bytes per row
        for (int row = 0; row < frameHeight; row++)
        {
            zlibStream.WriteByte(0);   // filter type 0 (None)
            zlibStream.Write(frameData.Slice(row * _width * 4, _width * 4));
        }
    }
    return memoryStream.ToArray();
}
```

