        lock (Gate)
        {
            if (s_recording is null)
            {
                s_recording = new Recording();
            }
        }
    }

    public static void StopRecording() => StopRecording(failureException: null);

    /// <summary>
    ///  Stops recording. When <paramref name="failureException"/> is not <see langword="null"/> the recording is
    ///  written out as an animated PNG next to the other failure artifacts.
    /// </summary>
    public static void StopRecording(Exception? failureException)
    {
        Recording? recording;
        lock (Gate)
        {
            recording = s_recording;
            s_recording = null;
        }

        recording?.Stop(failureException is not null, failureException);
    }

    private sealed class Recording : IDisposable
    {
        private readonly object _gate = new();
        private readonly System.Threading.Timer _timer;
        ...
    }
}
