        _disposed = true;
        // flush pending
        if (_pending is not null)
        {
            long now = _stopwatch.ElapsedMilliseconds;
            _writer.WriteFrame(_pending.Data, _pending.Height, _pending.YOffset, (uint)(now - _pending.StartMs));
