        {
            string fileName = DataCollectionService.CreateLogFileName("apng", failureException.GetType().Name);
            _writer.Finish();
            byte[] data = (_stream as MemoryStream).ToArray();
            Directory.CreateDirectory(Path.GetDirectoryName(fileName));
