```csharp
private static void WriteDataChunks(Stream stream, string type, byte[] data, ref uint sequence)
{
    if (type == "fdAT")
    {
        for (int offset = 0; offset < data.Length; offset += MaxChunkSize)
        {
            int count = Math.Min(MaxChunkSize, data.Length - offset);
            byte[] fdAtData = new byte[4 + count];
            BinaryPrimitives.WriteUInt32BigEndian(fdAtData, sequence++);
            Array.Copy(data, offset, fdAtData, 4, count);
            WriteChunk(stream, "fdAT", fdAtData);
        }
    }
    else
    {
        for (int offset = 0; offset < data.Length; offset += MaxChunkSize)
        {
            int count = Math.Min(MaxChunkSize, data.Length - offset);
            WriteChunk(stream, "IDAT", data.AsSpan(offset, count));
        }
    }
}
```

Allocation per chunk is fine (Finish-time).

