private void Capture(Bitmap bitmap, long currentMs)
{
    if (_width != bitmap.Width || _height != bitmap.Height)
    {
        // Screen size changed during recording (extremely unlikely); ignore the frame to avoid corrupting the canvas.
        bitmap.Dispose();
        return;
    }

    int height = _height;
    int rowLength = _width * 4;

    EnsureBuffers();
    // read into _rowBuffer as RGBA and compute hashes
    using (BitmapData data = bitmap.LockBits(new Rectangle(0, 0, _width, height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb))
    {
        IntPtr scan0 = data.Scan0;
        for (int y = 0; y < height; y++)
        {
            Marshal.Copy(scan0 + y * data.Stride, _rowBuffer, y * rowLength, rowLength);
            // swap B and R
            for (int x = y * rowLength; x < (y + 1) * rowLength; x += 4)
            {
                (_rowBuffer[x], _rowBuffer[x + 2]) = (_rowBuffer[x + 2], _rowBuffer[x]);
            }
            _hash.Reset();
            _hash.Append(_rowBuffer.AsSpan(y * rowLength, rowLength));
            _hashes[y] = _hash.GetCurrentHashAsUInt32();
        }
