using System.Buffers.Binary;
using System.Drawing;
using System.IO.Compression;
using System.IO.Hashing;
using System.Text;

namespace System.Windows.Forms.UITests;

/// <summary>
///  Encodes frames into an animated PNG (<c>APNG</c>) file.
/// </summary>
/// <remarks>
///  <para>
///   This is a small and deliberately simple encoder that can write the subset of the APNG specification that is
///   needed to record the screen during a UI test run:
///   <list type="bullet">
///    <item><description>A single default image frame (from <c>IDAT</c> chunks) followed by subsequent frames in
///    <c>fdAT</c> chunks.</description></item>
///    <item><description>Frames that cover a sub-region of the canvas (expressed with <see langword="y"/> offsets) so
///    that only the rows of the screen that actually changed need to be recorded.</description></item>
///    <item><description>Per-frame display delays expressed in milliseconds.</description></item>
///   </list>
///  </para>
///  <para>
///   Chunk and frame checksums are computed with <see cref="Crc32"/> from the <c>System.IO.Hashing</c> package.
///   The APNG specification can be found here: <see href="https://wiki.mozilla.org/APNG_Specification"/>.
///  </para>
/// </remarks>
internal sealed class ApngWriter
{
    // The longest a single frame can be displayed is 65.535 seconds as the delay is stored as a 16-bit value in
    // milliseconds (delay_num with a delay_den of 1000).
    public const int MaxFrameDelayMilliseconds = 65535;

    private const byte PngBitDepth = 8;
    private const byte PngColorTypeRgba = 6;
    private const byte PngCompressionMethod = 0;
    private const byte PngFilterMethod = 0;
    private const byte PngInterlaceMethod = 0;
    private const byte PngDisposeOpNone = 0;
    private const byte PngBlendOpSource = 0;
    private const ushort PngDelayDenominator = 1000;

    private const int StreamChunkSize = 8192;

    private static readonly byte[] s_pngSignature = [0x89, (byte)'P', (byte)'N', (byte)'G', 0x0D, 0x0A, 0x1A, 0x0A];

    private readonly int _width;
    private readonly List<FrameChunk> _frames = new();

    public ApngWriter(int width, int height)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(width);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(height);

        _width = width;
    }

    public int Height { get; }

    /// <summary>
    ///  Gets whether any frames have been written to this writer.
    /// </summary>
    public bool HasFrames => _frames.Count > 0;

    /// <summary>
    ///  Writes a frame that is displayed on screen for <paramref name="delayMilliseconds"/>.
    /// </summary>
    /// <param name="frameData">
    ///  The pixels of the frame as 32 bit ARGB data row-major order. Each row must contain exactly
    ///  <c>width</c> * 4 bytes. The frame only needs to contain the rows on the screen that changed; the topmost
    ///  recorded row is described by <paramref name="yOffset"/> and the frame is rendered over the previous frame
    ///  content.
    ///  </param>
    /// <param name="height">The number of rows in <paramref name="frameData"/>.</param>
    /// <param name="yOffset">The first row of the frame on the screen.</param>
    /// <param name="delayMilliseconds">How long the frame is displayed. If longer than one display period can
    ///  describe the frame is repeated as necessary to hold it on screen</param>
    public void WriteFrame(ReadOnlySpan<byte> frameData, int height, int yOffset, uint delayMilliseconds)
    {
        if (height < 0 || yOffset < 0)
        {
            throw new ArgumentOutOfRangeException();
        }

        if (frameData.Length != height * _width * sizeof(int))
        {
            throw new ArgumentException(SR.Frames_SizeMismatch, nameof(frameData));
        }

        if (delayMilliseconds == 0)
        {
            delayMilliseconds = 1;
        }

        byte[] compressed = Compress(frameData, height);

        // The delay is stored as a 16-bit millisecond value, so split long delays into multiple identical frames.
        do
        {
            _frames.Add(new FrameChunk(delayMilliseconds: Math.Min(delayMilliseconds, MaxFrameDelayMilliseconds), yOffset, height, compressed));

            if (delayMilliseconds <= MaxFrameDelayMilliseconds)
                break;

            delayMilliseconds -= MaxFrameDelayMilliseconds;
        }
        while (true);
    }

    /// <summary>
    ///  Writes the animated PNG that was started with <see cref="Start(Stream)"/> to <paramref name="stream"/>.
    /// </summary>
    public void Finish(Stream stream)
    {
        if (_frames.Count == 0)
            return;

        using var writer = ...
    }
}

