    // The longest a single frame can be displayed is 65.535 seconds as the delay is stored as a 16-bit value in
    // milliseconds (delay_num with a delay_den of 1000).
    public const int MaxFrameDelayMilliseconds = 65535;

    private const byte PngBitDepth = 8;
    private const byte PngColorTypeRgba = 6;
    private const byte PngCompressionMethod = 0;
    private const byte PngFilterMethod = 0;
    private const byte PngInterlaceMethod = 0;
    private const byte PngDisposeOpNone = 0;
    private const byte PngBlendOpSource = 0;
    private const ushort PngDelayDenominator = 1000;

    private const int StreamChunkSize = 8192;

    private static readonly byte[] s_pngSignature = [0x89, (byte)'P', (byte)'N', (byte)'G', 0x0D, 0x0A, 0x1A, 0x0A];

    private readonly int _width;
    private readonly int _height;
    private readonly List<FrameChunk> _frames = new();

    public ApngWriter(int width, int height)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(width);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(height);

        _width = width;
        _height = height;
    }

    /// <summary>
    ///  Gets whether any frames have been written to the animation.
    /// </summary>
    public bool HasFrames => _frames.Count > 0;

    /// <summary>
    ///  Writes a frame that is displayed on screen for <paramref name="delayMilliseconds"/>.
    /// </summary>
    /// <param name="frameData">
    ///  The pixels of the frame as 32 bit ARGB data in row-major order. Each row must contain exactly
    ///  <c>width</c> * 4 bytes. The frame only needs to contain the rows of the screen that changed; the topmost
    ///  recorded row is described by <paramref name="yOffset"/> and the frame is rendered over the previous frame
    ///  content.
    /// </param>
    /// <param name="height">The number of rows in <paramref name="frameData"/>.</param>
    /// <param name="yOffset">The first row of the frame on the screen.</param>
    /// <param name="delayMilliseconds">How long the frame is displayed on the screen before the next frame.</param>
    public void WriteFrame(ReadOnlySpan<byte> frameData, int height, int yOffset, uint delayMilliseconds)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(height);
        ArgumentOutOfRangeException.ThrowIfNegative(yOffset);

        if (frameData.Length != height * _width * sizeof(int))
        {
            throw new ArgumentException($"The frame data must contain exactly {_width * sizeof(int)} bytes per row.", nameof(frameData));
        }

        if (delayMilliseconds == 0)
        {
            delayMilliseconds = 1;
        }

        byte[] compressed = Compress(frameData, height);

        // The delay is stored as a 16-bit millisecond value, so split any delays that are too long to describe into
        // multiple identical frames.
        do
        {
            _frames.Add(new FrameChunk(delayMilliseconds: Math.Min(delayMilliseconds, MaxFrameDelayMilliseconds), yOffset, height, compressed));

            if (delayMilliseconds <= MaxFrameDelayMilliseconds)
                break;

            delayMilliseconds -= MaxFrameDelayMilliseconds;
        }
        while (true);
    }

    /// <summary>
    ///  Writes the animated PNG to <paramref name="stream"/>. Nothing is written if no frames were recorded.
    /// </summary>
    public void Finish(Stream stream)
    {
        if (_frames.Count == 0)
            return;

        Span<byte> buffer = stackalloc byte[13];

        // The PNG signature.
        stream.Write(s_pngSignature);

        // The image header.
        int offset = 0;
        WriteUInt32BigEndian(buffer, ref offset, (uint)_width);
        WriteUInt32BigEndian(buffer, ref offset, (uint)_height);
        buffer[offset++] = PngBitDepth;
        buffer[offset++] = PngColorTypeRgba;
        buffer[offset++] = PngCompressionMethod;
        buffer[offset++] = PngFilterMethod;
        buffer[offset++] = PngInterlaceMethod;
        WriteChunk(stream, "IHDR", buffer);

        // The animation control chunk, which describes how many frames the animation contains and how many times it
        // should play (0 means it plays indefinitely).
        offset = 0;
        WriteUInt32BigEndian(buffer, ref offset, (uint)_frames.Count);
        WriteUInt32BigEndian(buffer, ref offset, 0);
        WriteChunk(stream, "acTL", buffer);

        // The default image (written from IDAT chunks) is the first frame of the animation. Subsequent frames are
        // written from fdAT chunks.
        uint sequenceNumber = 0;
        for (int i = 0; i < _frames.Count; i++)
        {
            FrameChunk frame = _frames[i];
            WriteFrameControl(stream, ref sequenceNumber, frame);
            WriteFrameData(stream, i == 0 ? "IDAT" : "fdAT", frame.Data, ref sequenceNumber);
        }

        WriteChunk(stream, "IEND", ReadOnlySpan<byte>.Empty);
    }

    private byte[] Compress(ReadOnlySpan<byte> frameData, int height)
    {
        int bytesPerRow = _width * sizeof(int);

        using MemoryStream memoryStream = new();
        using (ZLibStream zlibStream = new(memoryStream, CompressionLevel.Optimal, leaveOpen: true))
        {
            for (int row = 0; row < height; row++)
            {
                // No filtering is applied to the rows, which keeps the encoder simple.
                zlibStream.WriteByte(PngFilterMethod);
                zlibStream.Write(frameData.Slice(row * bytesPerRow, bytesPerRow));
            }
        }

        return memoryStream.ToArray();
    }

    private void WriteFrameControl(Stream stream, ref uint sequenceNumber, FrameChunk frame)
    {
        Span<byte> buffer = stackalloc byte[26];
        int offset = 0;

        // The frame control chunk is followed by one sequence number per chunk. The sequence number is used to
        // detect duplicate or reordered chunks.
        WriteUInt32BigEndian(buffer, ref offset, sequenceNumber++);
        WriteUInt32BigEndian(buffer, ref offset, (uint)_width);
        WriteUInt32BigEndian(buffer, ref offset, (uint)frame.Height);
        WriteUInt32BigEndian(buffer, ref offset, 0);
        WriteUInt32BigEndian(buffer, ref offset, (uint)frame.YOffset);
        BinaryPrimitives.WriteUInt16BigEndian(buffer[offset..], (ushort)frame.DelayMilliseconds);
        offset += sizeof(ushort);
        BinaryPrimitives.WriteUInt16BigEndian(buffer[offset..], PngDelayDenominator);
        offset += sizeof(ushort);
        buffer[offset++] = PngDisposeOpNone;
        buffer[offset++] = PngBlendOpSource;

        WriteChunk(stream, "fcTL", buffer);
    }

    private void WriteFrameData(Stream stream, string type, ReadOnlySpan<byte> data, ref uint sequenceNumber)
    {
        for (int offset = 0; offset < data.Length; offset += StreamChunkSize)
        {
            int count = Math.Min(StreamChunkSize, data.Length - offset);

            if (type == "IDAT")
            {
                // IDAT chunks do not carry a sequence number.
                WriteChunk(stream, type, data.Slice(offset, count));
            }
            else
            {
                // fdAT chunks are identified by a sequence number that is part of the chunk data.
                byte[] chunkData = new byte[sizeof(uint) + count];
                BinaryPrimitives.WriteUInt32BigEndian(chunkData, sequenceNumber++);
                data.Slice(offset, count).CopyTo(chunkData.AsSpan(sizeof(uint)));
                WriteChunk(stream, type, chunkData);
            }
        }
    }

    private static void WriteChunk(Stream stream, string type, ReadOnlySpan<byte> data)
    {
        Span<byte> buffer = stackalloc byte[sizeof(uint)];

        BinaryPrimitives.WriteUInt32BigEndian(buffer, (uint)data.Length);
        stream.Write(buffer);

        ReadOnlySpan<byte> typeBytes = Encoding.ASCII.GetBytes(type);
        stream.Write(typeBytes);
        stream.Write(data);

        // Every chunk carries a checksum (CRC-32) of the type and data, which is how corrupted or truncated files
        // are detected.
        Crc32 crc = new();
        crc.Append(typeBytes);
        crc.Append(data);
        BinaryPrimitives.WriteUInt32BigEndian(buffer, crc.GetCurrentHashAsUInt32());
        stream.Write(buffer);
    }

    private static void WriteUInt32BigEndian(Span<byte> buffer, ref int offset, uint value)
    {
        BinaryPrimitives.WriteUInt32BigEndian(buffer[offset..], value);
        offset += sizeof(uint);
    }

    private readonly record struct FrameChunk(uint DelayMilliseconds, int YOffset, int Height, byte[] Data);
}

