using System.Drawing;
using System.Drawing.Imaging;
using System.IO.Hashing;
using System.Runtime.InteropServices;

namespace System.Windows.Forms.UITests;

/// <summary>
///  Records a screen capture of a UI test run to an animated PNG.
/// </summary>
/// <remarks>
///  <para>
///   Recording is started by <see cref="StartRecording"/> and stopped by <see cref="StopRecording(Exception?)"/>. The
///   screen is captured at a low frame rate until recording is stopped. When a test fails, the recording is written
///   to an animated PNG file that is stored alongside the other test failure artifacts (for example logs and
///   screenshots).
///  </para>
///  <para>
///   To keep the recordings small, a checksum of every captured row is computed with <see cref="Crc32"/> and
///   unchanged frames are coalesced into a single frame. When the screen changes, only the rows that actually
///   changed are written to the animation, which typically reduces the size of a recording substantially.
///  </para>
/// </remarks>
internal static class VideoRecorderService
{
    // The frame rate is deliberately low. Screen captures are expensive and the resulting file size is proportional
    // to the number of captured frames.
    public const int FramesPerSecond = 4;

    private static readonly object Gate = new();
    private static Recording? s_recording;

    /// <summary>
    ///  Starts recording the screen. Only one recording is active at a time; if a recording is already in progress it
    ///  is left alone.
    /// </summary>
    public static void StartRecording()
    {
        lock (Gate)
        {
            if (s_recording is null)
            {
                s_recording = new Recording();
            }
        }
    }

    /// <summary>
    ///  Stops the current screen recording and discards it.
    /// </summary>
    public static void StopRecording() => StopRecording(failureException: null);

    /// <summary>
    ///  Stops the current screen recording. When <paramref name="failureException"/> is not <see langword="null"/>
    ///  the recording is written to an animated PNG file next to the other failure artifacts.
    /// </summary>
    /// <param name="failureException">
    ///  The exception that failed the test, or <see langword="null"/> if the test completed successfully.
    /// </param>
    public static void StopRecording(Exception? failureException)
    {
        Recording? recording;
        lock (Gate)
        {
            recording = s_recording;
            s_recording = null;
        }

        recording?.Stop(writeAnimatedPng: failureException is not null, failureException);
    }

    private sealed class Recording : IDisposable
    {
        private readonly object _gate = new();
        private readonly Crc32 _hash = new();
        private readonly Stopwatch _stopwatch = new();
        private readonly ApngWriter? _writer;
        private readonly int _width;
        private readonly int _height;

        private Timer? _timer;
        private byte[]? _rowBuffer;
        private uint[]? _rowHashes;
        private uint[]? _committedRowHashes;
        private byte[]? _pendingData;
        private int _pendingYOffset;
        private int _pendingHeight;
        private uint[]? _pendingHashes;
        private long _pendingStartMs;
        private bool _hasPending;

        public Recording()
        {
            _stopwatch.Start();

            // Establish the canvas and capture the first frame synchronously, before the timer is started. This
            // ensures there is always content to work from, even for very short test runs, and that the first frame
            // is always a full copy of the screen.
            using Bitmap? firstFrame = ScreenshotService.TryCaptureFullScreen();
            if (firstFrame is null)
            {
                // A screen capture cannot be taken (for example when running without an interactive desktop), so
                // recording is disabled.
                return;
            }

            _width = firstFrame.Width;
            _height = firstFrame.Height;
            _writer = new ApngWriter(_width, _height);

            Capture(firstFrame);

            _timer = new Timer(OnTimerTick, null, Timeout.Infinite, Timeout.Infinite);
            _timer.Change(intervalMs, intervalMs);
        }

        private int intervalMs => 1000 / FramesPerSecond;

        public void Stop(bool writeAnimatedPng, Exception? failureException)
        {
            Dispose();

            lock (_gate)
            {
                if (_writer is { } writer && _hasPending)
                {
                    // Flush the frame that is still on the screen.
                    uint duration = (uint)Math.Max(0, _stopwatch.ElapsedMilliseconds - _pendingStartMs);
                    writer.WriteFrame(_pendingData!, _pendingHeight, _pendingYOffset, duration);
                    _hasPending = false;
                }
            }

            if (writeAnimatedPng && _writer is { HasFrames: true } recording)
            {
                string fileName = DataCollectionService.CreateLogFileName("apng", failureException?.GetType().Name ?? "Unknown");
                try
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(fileName)!);
                    using FileStream stream = File.Create(fileName);
                    recording.Finish(stream);
                }
                catch
                {
                    // Never let a recording failure interfere with the test results.
                }
            }
        }

        public void Dispose()
        {
            lock (_gate)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }

        private void OnTimerTick(object? state)
        {
            lock (_gate)
            {
                if (_writer is null || _timer is null)
                    return;

                using Bitmap? current = ScreenshotService.TryCaptureFullScreen();
                if (current is not null)
                {
                    Capture(current);
                }
            }
        }

        private void Capture(Bitmap bitmap)
        {
            try
            {
                if (bitmap.Width != _width || bitmap.Height != _height)
                {
                    // The screen size cannot change during a recording. Ignore the frame so the animation canvas
                    // stays consistent.
                    return;
                }

                int bytesPerRow = _width * sizeof(int);
                EnsureBuffers();

                using (BitmapData data = bitmap.LockBits(new Rectangle(0, 0, _width, _height), ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb))
                {
                    nint scan0 = data.Scan0;
                    for (int y = 0; y < _height; y++)
                    {
                        int rowOffset = y * bytesPerRow;
                        Marshal.Copy(scan0 + (y * data.Stride), _rowBuffer!, rowOffset, bytesPerRow);

                        // The screenshot helper only produces 32 bit ARGB images, which are stored in memory in BGRA
                        // order. Swap the red and blue channels so the rows are in RGBA order for the encoder.
                        for (int x = rowOffset; x < rowOffset + bytesPerRow; x += sizeof(int))
                        {
                            (_rowBuffer![x], _rowBuffer[x + 2]) = (_rowBuffer[x + 2], _rowBuffer[x]);
                        }

                        _hash.Reset();
                        _hash.Append(_rowBuffer.AsSpan(rowOffset, bytesPerRow));
                        _rowHashes![y] = _hash.GetCurrentHashAsUInt32();
                    }
                }

                if (_hasPending && HashesEqual(_pendingHashes!, _rowHashes!))
                {
                    // The screen hasn't changed since the pending frame started, so there is nothing to record.
                    return;
                }

                if (_hasPending)
                {
                    // The pending frame is complete. Record it and use its content as the reference for the next
                    // frame.
                    uint duration = (uint)Math.Max(1, _stopwatch.ElapsedMilliseconds - _pendingStartMs);
                    _writer!.WriteFrame(_pendingData!, _pendingHeight, _pendingYOffset, duration);
                    _committedRowHashes = _pendingHashes;
                }
                else
                {
                    _committedRowHashes = null;
                }

                // Find the range of rows that changed and record only those rows of the new frame.
                int firstRow = 0;
                int rowCount = _height;
                if (_committedRowHashes is not null && _committedRowHashes.Length == _height)
                {
                    int firstDirtyRow = -1;
                    int lastDirtyRow = -1;
                    for (int y = 0; y < _height; y++)
                    {
                        if (_rowHashes![y] != _committedRowHashes[y])
                        {
                            if (firstDirtyRow < 0)
                                firstDirtyRow = y;
                            lastDirtyRow = y;
                        }
                    }

                    if (firstDirtyRow >= 0)
                    {
                        firstRow = firstDirtyRow;
                        rowCount = lastDirtyRow - firstDirtyRow + 1;
                    }
                }

                _pendingData = new byte[rowCount * bytesPerRow];
                Buffer.BlockCopy(_rowBuffer!, firstRow * bytesPerRow, _pendingData, 0, _pendingData.Length);
                _pendingYOffset = firstRow;
                _pendingHeight = rowCount;
                _pendingHashes = (uint[])_rowHashes!.Clone();
                _pendingStartMs = _stopwatch.ElapsedMilliseconds;
                _hasPending = true;
            }
            finally
            {
                bitmap.Dispose();
            }
        }

        private void EnsureBuffers()
        {
            if (_rowBuffer is null || _rowBuffer.Length != _width * _height * sizeof(int))
            {
                _rowBuffer = new byte[_width * _height * sizeof(int)];
            }

            if (_rowHashes is null || _rowHashes.Length != _height)
            {
                _rowHashes = new uint[_height];
            }
        }

        private static bool HashesEqual(uint[] left, uint[] right)
        {
            if (ReferenceEquals(left, right))
                return true;

            if (left.Length != right.Length)
                return false;

            for (int i = 0; i < left.Length; i++)
            {
                if (left[i] != right[i])
                    return false;
            }

            return true;
        }
    }
}

