// Offline stand-in for System.IO.Hashing.Crc32 (the real package implements IEEE 802.3 CRC-32, the same
// "PNG/zlib" polynomial used here). This lets the real ApngWriter.cs compile and run without the NuGet package.

namespace System.IO.Hashing;

public sealed class Crc32
{
    private static readonly uint[] s_table = CreateTable();
    private uint _crc = uint.MaxValue;

    public void Append(ReadOnlySpan<byte> source)
    {
        uint crc = _crc;
        foreach (byte b in source)
        {
            crc = s_table[(byte)(crc ^ b)] ^ (crc >> 8);
        }
        _crc = crc;
    }

    public void Reset() => _crc = uint.MaxValue;

    public uint GetCurrentHashAsUInt32() => ~_crc;

    private static uint[] CreateTable()
    {
        uint[] table = new uint[256];
        for (int i = 0; i < 256; i++)
        {
            uint crc = (uint)i;
            for (int j = 0; j < 8; j++)
            {
                crc = (crc & 1) != 0 ? 0xEDB88320u ^ (crc >> 1) : crc >> 1;
            }
            table[i] = crc;
        }
        return table;
    }
}

// Offline validation of the real ApngWriter.cs: writes frames (including sub-region bands, delay splitting, and
// multi-chunk IDAT/fdAT) and then independently parses the resulting bytes to verify the APNG structure, chunk
// checksums, sequence numbers, frame controls, and decompressed pixel content.

using System.IO.Compression;
using System.Text;
using System.Windows.Forms.UITests;

static class Test
{
    static int Checks;
    static int Failed;

    static void Check(bool condition, string name)
    {
        Checks++;
        if (!condition)
        {
            Failed++;
            Console.WriteLine($"  FAIL: {name}");
        }
    }

    static void Main()
    {
        const int Width = 160;
        const int Height = 100;
        int bytesPerRow = Width * 4;

        byte[] Frame0() => FullFrame(Width, Height, offset: 0);
        byte[] FrameA() => FullFrame(Width, Height, offset: 1);

        byte[] full0 = Frame0();
        byte[] fullA = FrameA();

        // Band rows 10..19 of "fullA" (20 rows).
        byte[] band = new byte[20 * bytesPerRow];
        Buffer.BlockCopy(fullA, 10 * bytesPerRow, band, 0, band.Length);

        ApngWriter writer = new(Width, Height);
        writer.WriteFrame(full0, Height, 0, delayMilliseconds: 250);
        writer.WriteFrame(band, 20, 10, delayMilliseconds: 500);
        writer.WriteFrame(band, 20, 10, delayMilliseconds: 70000);   // must split into 65535 + 4465

        MemoryStream output = new();
        writer.Finish(output);
        byte[] bytes = output.ToArray();

        Parse(bytes, callback: null);

        List<Chunk> chunks = Parse(bytes, null);
        Check(chunks.Count >= 8, $"parsed chunks (got {chunks.Count})");
        Check(chunks[0].Type == "IHDR", "first chunk is IHDR");

        int seq = 0;
        Check(chunks[1].Type == "acTL", "second chunk is acTL");
        uint numFrames = ReadU32(chunks[1].Data, 0);
        uint numPlays = ReadU32(chunks[1].Data, 4);
        Check(numFrames == 4, $"acTL num_frames == 4 (got {numFrames})");
        Check(numPlays == 0, "acTL num_plays == 0 (loop forever)");

        uint width = ReadU32(chunks[0].Data, 0);
        uint height = ReadU32(chunks[0].Data, 4);
        Check(width == Width && height == Height, $"IHDR dimensions {width}x{height}");
        Check(chunks[0].Data[8] == 8, "IHDR bit depth 8");
        Check(chunks[0].Data[9] == 6, "IHDR color type RGBA (6)");

        // Frame controls and data.
        uint[] expectedDelays = [250, 500, 65535, 4465];
        int[] expectedYOffsets = [0, 10, 10, 10];
        int[] expectedHeights = [Height, 20, 20, 20];
        int frameIndex = 0;
        int fdAtCount = 0;

        for (int i = 2; i < chunks.Count; i++)
        {
            switch (chunks[i].Type)
            {
                case "fcTL":
                    Check(ReadU32(chunks[i].Data, 0) == seq, $"fcTL[{frameIndex}] sequence {seq}");
                    seq++;
                    uint fw = ReadU32(chunks[i].Data, 4);
                    uint fh = ReadU32(chunks[i].Data, 8);
                    uint xOff = ReadU32(chunks[i].Data, 12);
                    uint yOff = ReadU32(chunks[i].Data, 16);
                    ushort delayNum = ReadU16(chunks[i].Data, 20);
                    ushort delayDen = ReadU16(chunks[i].Data, 22);
                    byte disposeOp = chunks[i].Data[24];
                    byte blendOp = chunks[i].Data[25];

                    Check(fw == Width, $"fcTL[{frameIndex}] width == {Width}");
                    Check(fh == expectedHeights[frameIndex], $"fcTL[{frameIndex}] height == {expectedHeights[frameIndex]} (got {fh})");
                    Check(xOff == 0, $"fcTL[{frameIndex}] x offset 0");
                    Check(yOff == expectedYOffsets[frameIndex], $"fcTL[{frameIndex}] y offset == {expectedYOffsets[frameIndex]} (got {yOff})");
                    Check(delayNum == expectedDelays[frameIndex], $"fcTL[{frameIndex}] delay_num == {expectedDelays[frameIndex]} (got {delayNum})");
                    Check(delayDen == 1000, $"fcTL[{frameIndex}] delay_den == 1000");
                    Check(disposeOp == 0, $"fcTL[{frameIndex}] dispose_op none (0)");
                    Check(blendOp == 0, $"fcTL[{frameIndex}] blend_op source (0)");

                    frameIndex++;
                    break;

                case "IDAT":
                    Check(frameIndex == 1, $"IDAT present exactly once, for first frame (frameIndex={frameIndex})");
                    break;

                case "fdAT":
                    Check(ReadU32(chunks[i].Data, 0) == seq, $"fdAT sequence {seq}");
                    seq++;
                    fdAtCount++;
                    break;
            }
        }

        Check(frameIndex == 4, $"four frame controls (got {frameIndex})");
        Check(fdAtCount >= 3, $"fdAT chunks present for frames 2-4 (got {fdAtCount})");
        Check(chunks[^1].Type == "IEND", "last chunk is IEND");
        Check(chunks[^1].Data.Length == 0, "IEND is empty");

        // Decompress and compare each frame against the input data.
        byte[] iDat = Concat(ChunksOfType(chunks).Where(c => c.Type == "IDAT"));
        byte[] fDatPart1 = Concat(ChunksOfType(chunks).Where(c => c.Type == "fdAT")).Skip(4).ToArray(); // strip first seq
        // For simplicity, only the first fdAT blob is compared (covers frame 2). Frame 3/4 share the same content.
        byte[] decompressed0 = Inflate(iDat);
        Check(CompareFrame(decompressed0, Height, bytesPerRow), "frame 0 decompresses to the exact input pixels");

        byte[] fdAt0 = ChunksOfType(chunks).Where(c => c.Type == "fdAT").First().Data;
        byte[] frame2 = Inflate(fdAt0[4..]);
        Check(frame2.Length == 20 * (1 + bytesPerRow), $"frame 2 decompressed length ({frame2.Length})");
        Check(CompareRows(frame2, band, 20, bytesPerRow), "frame 2 band decompresses to exact input band pixels");

        // Independent CRC-32 cross check (bitwise implementation) against the chunk checksums the writer wrote.
        ValidateCrcs(bytes);

        Console.WriteLine($"Total: {Checks} checks, {Failed} failures.");
        Environment.Exit(Failed == 0 ? 0 : 1);
    }

    static byte[] FullFrame(int width, int height, int offset)
    {
        byte[] data = new byte[width * height * 4];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int i = (y * width + x) * 4;
                data[i] = (byte)((x + offset) * 3 & 0xFF);          // R
                data[i + 1] = (byte)((y + offset) * 5 & 0xFF);      // G
                data[i + 2] = (byte)((x - y + offset) & 0xFF);      // B
                data[i + 3] = 0xFF;                                  // A
            }
        }
        return data;
    }

    static bool CompareFrame(byte[] decompressed, int height, int bytesPerRow)
    {
        // Each row in the decompressed stream is prefixed with a one byte filter type (0 = None).
        int expected = height * (1 + bytesPerRow);
        if (decompressed.Length != expected)
            return false;

        byte[] full0 = FullFrame(160, 100, 0);
        for (int y = 0; y < height; y++)
        {
            int rowStart = y * (1 + bytesPerRow);
            if (decompressed[rowStart] != 0)
                return false; // filter type must be None
            for (int x = 0; x < bytesPerRow; x++)
            {
                if (decompressed[rowStart + 1 + x] != full0[y * bytesPerRow + x])
                    return false;
            }
        }

        return true;
    }

    static bool CompareRows(byte[] decompressed, byte[] input, int height, int bytesPerRow)
    {
        if (decompressed.Length != height * (1 + bytesPerRow))
            return false;

        for (int y = 0; y < height; y++)
        {
            int rowStart = y * (1 + bytesPerRow);
            if (decompressed[rowStart] != 0)
                return false;
            for (int x = 0; x < bytesPerRow; x++)
            {
                if (decompressed[rowStart + 1 + x] != input[y * bytesPerRow + x])
                    return false;
            }
        }

        return true;
    }

    static byte[] Inflate(ReadOnlySpan<byte> zlibData)
    {
        using MemoryStream input = new(zlibData.ToArray());
        using ZLibStream zlib = new(input, CompressionMode.Decompress, leaveOpen: false);
        using MemoryStream output = new();
        zlib.CopyTo(output);
        return output.ToArray();
    }

    static void ValidateCrcs(byte[] bytes)
    {
        int pos = 8; // skip signature
        while (pos + 12 <= bytes.Length)
        {
            uint length = ReadU32(bytes, pos);
            pos += 4;
            string type = Encoding.ASCII.GetString(bytes, pos, 4);
            pos += 4;
            ReadOnlySpan<byte> data = bytes.AsSpan(pos, (int)length);
            pos += (int)length;

            uint stored = ReadU32(bytes, pos);
            pos += 4;

            uint expected = IndependentCrc32(bytes.AsSpan(pos - 4 - (int)length, (int)length + 4));
            Check(stored == expected, $"CRC-32 for chunk {type}");
        }
    }

    static uint IndependentCrc32(ReadOnlySpan<byte> data)
    {
        uint crc = 0xFFFFFFFFu;
        for (int i = 0; i < data.Length; i++)
        {
            crc ^= data[i];
            for (int j = 0; j < 8; j++)
            {
                crc = (crc & 1) != 0 ? 0xEDB88320u ^ (crc >> 1) : crc >> 1;
            }
        }
        return ~crc;
    }

    static byte[] Concat(IEnumerable<byte[]> parts)
    {
        using MemoryStream ms = new();
        foreach (byte[] part in parts)
            ms.Write(part);
        return ms.ToArray();
    }

    static IEnumerable<byte[]> ChunksOfType(List<Chunk> chunks) => chunks.Select(c => c.Data);

    static uint ReadU32(ReadOnlySpan<byte> data, int offset)
    {
        return (uint)((data[offset] << 24) | (data[offset + 1] << 16) | (data[offset + 2] << 8) | data[offset + 3]);
    }

    static ushort ReadU16(ReadOnlySpan<byte> data, int offset)
    {
        return (ushort)((data[offset] << 8) | data[offset + 1]);
    }

    static List<Chunk> Parse(byte[] bytes, Action<Chunk>? callback)
    {
        List<Chunk> chunks = new();
        int pos = 8;
        Check(bytes.Length >= 8 && bytes[0] == 0x89 && bytes[1] == (byte)'P' && bytes[2] == (byte)'N' && bytes[3] == (byte)'G', "PNG signature");

        while (pos + 12 <= bytes.Length)
        {
            uint length = ReadU32(bytes, pos);
            pos += 4;
            string type = Encoding.ASCII.GetString(bytes, pos, 4);
            Chunk chunk = new(type, bytes.AsSpan(pos + 4, (int)length).ToArray());
            chunks.Add(chunk);
            pos += (int)length + 4;
            callback?.Invoke(chunk);
        }

        return chunks;
    }

    readonly record struct Chunk(string Type, byte[] Data);
}

