        for (int y=0;y<height;y++) for(int x=0;x<width;x++){int i=(y*width+x)*4; d[i]=(byte)((x+offset)*3&0xFF); d[i+1]=(byte)((y+offset)*5&0xFF); d[i+2]=(byte)((x-y+offset)&0xFF); d[i+3]=0xFF;}
        return d;
    }
    static void Main()
    {
        int Width=160, Height=100, bpr=Width*4;
        byte[] full0 = Full(Width, Height, 0);
        byte[] fullA = Full(Width, Height, 1);
        byte[] band = new byte[20*bpr];
        Buffer.BlockCopy(fullA, 10*bpr, band, 0, band.Length);

        byte[] reference = RefCompress(band);
        Console.WriteLine($"reference zlib bytes: {reference.Length} first12={Convert.ToHexString(reference,0,12)}");

        ApngWriter w = new(Width, Height);
        w.WriteFrame(full0, Height, 0, 250);
        w.WriteFrame(band, 20, 10, 500);
        w.WriteFrame(band, 20, 10, 70000);
        using MemoryStream ms = new();
        w.Finish(ms);
        byte[] bytes = ms.ToArray();
        int pos=8;
        while (pos < bytes.Length)
        {
            if (pos+12>bytes.Length) break;
            uint len = ReadU32(bytes, pos);
            string type = Encoding.ASCII.GetString(bytes, pos+4, 4);
            if (type == "fdAT" || type == "IDAT")
            {
                byte[] data = bytes.AsSpan(pos+8, (int)len).ToArray();
                Console.WriteLine($"  {type} len={len} first16={Convert.ToHexString(data,0,Math.Min(16,data.Length))}");
                if (type == "fdAT" && len > 4+4)
                {
                    byte[] comp = data[4..];
                    Console.WriteLine($"    comp first12={Convert.ToHexString(comp,0,Math.Min(12,comp.Length))} equal-to-reference={comp.AsSpan().SequenceEqual(reference)}");
                }
            }
            pos += 12 + (int)len;
        }
    }
