// Offline validation of the real ApngWriter.cs: writes frames (including sub-region bands, delay splitting, and
// multi-chunk IDAT/fdAT) and then independently parses the resulting bytes to verify the APNG structure, chunk
// checksums, sequence numbers, frame controls, and decompressed pixel content.

using System.IO.Compression;
using System.Text;
using System.Windows.Forms.UITests;

static class Test
{
    static int Checks;
    static int Failed;

    static void Check(bool condition, string name)
    {
        Checks++;
        if (!condition)
        {
            Failed++;
            Console.WriteLine($"  FAIL: {name}");
        }
    }

    static void Main()
    {
        const int Width = 160;
        const int Height = 100;
        int bytesPerRow = Width * 4;

        byte[] full0 = FullFrame(Width, Height, offset: 0);
        byte[] fullA = FullFrame(Width, Height, offset: 1);

        // Band rows 10..29 of "fullA" (20 rows).
        byte[] band = new byte[20 * bytesPerRow];
        Buffer.BlockCopy(fullA, 10 * bytesPerRow, band, 0, band.Length);

        ApngWriter writer = new(Width, Height);
        writer.WriteFrame(full0, Height, 0, delayMilliseconds: 250);
        writer.WriteFrame(band, 20, 10, delayMilliseconds: 500);
        writer.WriteFrame(band, 20, 10, delayMilliseconds: 70000);   // must split into 65535 + 4465

        using MemoryStream output = new();
        writer.Finish(output);
        byte[] bytes = output.ToArray();

        List<Chunk> chunks = Parse(bytes);

        Check(chunks[0].Type == "IHDR", "first chunk is IHDR");
        Check(chunks[1].Type == "acTL", "second chunk is acTL");
        Check(ReadU32(chunks[1].Data, 0) == 4, "acTL num_frames == 4");
        Check(ReadU32(chunks[1].Data, 4) == 0, "acTL num_plays == 0 (loop forever)");
        Check(ReadU32(chunks[0].Data, 0) == Width, "IHDR width");
        Check(ReadU32(chunks[0].Data, 4) == Height, "IHDR height");
        Check(chunks[0].Data[8] == 8, "IHDR bit depth 8");
        Check(chunks[0].Data[9] == 6, "IHDR color type RGBA (6)");
        Check(chunks[^1].Type == "IEND" && chunks[^1].Data.Length == 0, "IEND empty chunk");

        // Split the chunks into frames. Each fcTL starts a frame; the (single) IDAT or following fdAT chunks are the
        // frame payload.
        List<Frame> frames = new();
        Frame? current = null;
        foreach (Chunk chunk in chunks)
        {
            switch (chunk.Type)
            {
                case "fcTL":
                    current = new Frame
                    {
                        SequenceNumber = ReadU32(chunk.Data, 0),
                        Width = ReadU32(chunk.Data, 4),
                        FrameHeight = ReadU32(chunk.Data, 8),
                        YOffset = ReadU32(chunk.Data, 16),
                        DelayNum = ReadU16(chunk.Data, 20),
                        DelayDen = ReadU16(chunk.Data, 22),
                        DisposeOp = chunk.Data[24],
                        BlendOp = chunk.Data[25],
                    };
                    frames.Add(current);
                    break;
                case "IDAT":
                    current!.IdatData.AddRange(chunk.Data);
                    break;
                case "fdAT":
                    current!.FdatSeqs.Add(ReadU32(chunk.Data, 0));   // first 4 bytes are the sequence number
                    current.IdatData.AddRange(chunk.Data[4..]);       // remainder is frame data
                    break;
            }
        }

        // Sequence numbers must be strictly sequential for all fcTL and fdAT chunks (IDAT has none).
        List<uint> sequenceNumbers = new();
        foreach (Chunk chunk in chunks)
        {
            if (chunk.Type == "fcTL")
                sequenceNumbers.Add(ReadU32(chunk.Data, 0));
            else if (chunk.Type == "fdAT")
                sequenceNumbers.Add(ReadU32(chunk.Data, 0));
        }
        Check(sequenceNumbers.Count == 7, $"7 sequential chunk numbers (got {sequenceNumbers.Count})");
        for (int i = 0; i < sequenceNumbers.Count; i++)
            Check(sequenceNumbers[i] == i, $"chunk sequence number {i}");

        Check(frames.Count == 4, $"four frames parsed (got {frames.Count})");

        uint[] expectedDelays = [250, 500, 65535, 4465];
        for (int i = 0; i < frames.Count; i++)
        {
            Frame frame = frames[i];
            Check(frame.Width == Width, $"frame {i} width");
            Check(frame.FrameHeight == (i == 0 ? Height : 20u), $"frame {i} height ({frame.FrameHeight})");
            Check(frame.YOffset == (i == 0 ? 0u : 10u), $"frame {i} y offset ({frame.YOffset})");
            Check(frame.DelayNum == expectedDelays[i], $"frame {i} delay {expectedDelays[i]} (got {frame.DelayNum})");
            Check(frame.DelayDen == 1000, $"frame {i} delay denominator 1000");
            Check(frame.DisposeOp == 0 && frame.BlendOp == 0, $"frame {i} dispose/blend SOURCE+NONE");
            Check(frame.IdatData.Count > 0, $"frame {i} has frame data");
        }

        // The first frame must be the IDAT frame (no fdAT sequence numbers).
        Check(frames[0].FdatSeqs.Count == 0, "first frame carried by IDAT");
        for (int i = 1; i < frames.Count; i++)
            Check(frames[i].FdatSeqs.Count >= 1, $"frame {i} carried by fdAT");

        // Decompress and compare the pixel content.
        byte[] decompressed0 = Inflate(frames[0].IdatData.ToArray());
        Check(CompareFrame(decompressed0, Height, bytesPerRow), "frame 0 decompresses to exact input pixels");

        byte[] decompressed1 = Inflate(frames[1].IdatData.ToArray());
        Check(decompressed1.Length == 20 * (1 + bytesPerRow), $"frame 1 decompressed length ({decompressed1.Length})");
        Check(CompareRows(decompressed1, band, 20, bytesPerRow), "frame 1 band decompresses to exact input band pixels");

        // Frames 2 and 3 are identical split frames, so they must share the compressed payload.
        Check(frames[2].IdatData.SequenceEqual(frames[1].IdatData), "frame 2 (split) shares payload of frame 1");
        Check(frames[3].IdatData.SequenceEqual(frames[1].IdatData), "frame 3 (split) shares payload of frame 1");

        // Every chunk checksum must match an independent bitwise CRC-32 of the chunk type and data.
        ValidateCrcs(bytes);

        Console.WriteLine($"Total: {Checks} checks, {Failed} failures.");
        Environment.Exit(Failed == 0 ? 0 : 1);
    }

    static byte[] FullFrame(int width, int height, int offset)
    {
        byte[] data = new byte[width * height * 4];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int i = (y * width + x) * 4;
                data[i] = (byte)((x + offset) * 3 & 0xFF);          // R
                data[i + 1] = (byte)((y + offset) * 5 & 0xFF);      // G
                data[i + 2] = (byte)((x - y + offset) & 0xFF);      // B
                data[i + 3] = 0xFF;                                  // A
            }
        }
        return data;
    }

    static bool CompareFrame(byte[] decompressed, int height, int bytesPerRow)
    {
        // Each row in the decompressed stream is prefixed with a one byte filter type (0 = None).
        int expected = height * (1 + bytesPerRow);
        if (decompressed.Length != expected)
            return false;

        byte[] full0 = FullFrame(160, 100, 0);
        for (int y = 0; y < height; y++)
        {
            int rowStart = y * (1 + bytesPerRow);
            if (decompressed[rowStart] != 0)
                return false; // filter type must be None
            for (int x = 0; x < bytesPerRow; x++)
            {
                if (decompressed[rowStart + 1 + x] != full0[y * bytesPerRow + x])
                    return false;
            }
        }

        return true;
    }

    static bool CompareRows(byte[] decompressed, byte[] input, int height, int bytesPerRow)
    {
        if (decompressed.Length != height * (1 + bytesPerRow))
            return false;

        for (int y = 0; y < height; y++)
        {
            int rowStart = y * (1 + bytesPerRow);
            if (decompressed[rowStart] != 0)
                return false;
            for (int x = 0; x < bytesPerRow; x++)
            {
                if (decompressed[rowStart + 1 + x] != input[y * bytesPerRow + x])
                    return false;
            }
        }

        return true;
    }

    static byte[] Inflate(ReadOnlySpan<byte> zlibData)
    {
        using MemoryStream input = new(zlibData.ToArray());
        using ZLibStream zlib = new(input, CompressionMode.Decompress);
        using MemoryStream output = new();
        zlib.CopyTo(output);
        return output.ToArray();
    }

    static void ValidateCrcs(byte[] bytes)
    {
        int pos = 8; // skip the signature
        while (pos + 12 <= bytes.Length)
        {
            int length = (int)ReadU32(bytes, pos);
            ReadOnlySpan<byte> typeAndData = bytes.AsSpan(pos + 4, 4 + length);
            uint stored = ReadU32(bytes, pos + 8 + length);
            uint expected = IndependentCrc32(typeAndData);
            Check(stored == expected, $"CRC-32 for chunk {Encoding.ASCII.GetString(bytes, pos + 4, 4)}");
            pos += 12 + length;
        }
    }

    static uint IndependentCrc32(ReadOnlySpan<byte> data)
    {
        uint crc = 0xFFFFFFFFu;
        for (int i = 0; i < data.Length; i++)
        {
            crc ^= data[i];
            for (int j = 0; j < 8; j++)
            {
                crc = (crc & 1) != 0 ? 0xEDB88320u ^ (crc >> 1) : crc >> 1;
            }
        }
        return ~crc;
    }

    static uint ReadU32(ReadOnlySpan<byte> data, int offset)
    {
        return (uint)((data[offset] << 24) | (data[offset + 1] << 16) | (data[offset + 2] << 8) | data[offset + 3]);
    }

    static ushort ReadU16(ReadOnlySpan<byte> data, int offset)
    {
        return (ushort)((data[offset] << 8) | data[offset + 1]);
    }

    static List<Chunk> Parse(byte[] bytes)
    {
        Check(bytes.Length >= 8 && bytes[0] == 0x89 && bytes[1] == (byte)'P' && bytes[2] == (byte)'N' && bytes[3] == (byte)'G', "PNG signature");

        List<Chunk> chunks = new();
        int pos = 8;
        while (pos + 12 <= bytes.Length)
        {
            uint length = ReadU32(bytes, pos);
            pos += 4;
            string type = Encoding.ASCII.GetString(bytes, pos, 4);
            chunks.Add(new Chunk(type, bytes.AsSpan(pos + 4, (int)length).ToArray()));
            pos += (int)length + 8;
        }

        return chunks;
    }

    readonly record struct Chunk(string Type, byte[] Data);

    sealed class Frame
    {
        public uint SequenceNumber { get; init; }
        public uint Width { get; init; }
        public uint FrameHeight { get; init; }
        public uint YOffset { get; init; }
        public ushort DelayNum { get; init; }
        public ushort DelayDen { get; init; }
        public byte DisposeOp { get; init; }
        public byte BlendOp { get; init; }
        public List<uint> FdatSeqs { get; } = new();
        public List<byte> IdatData { get; } = new();
    }
}

