// Minimal stand-ins that let the real VideoRecorderService.cs and ApngWriter.cs compile and run without
// System.Drawing.Common or the WinForms test infrastructure.

using System.Runtime.InteropServices;

namespace System.Drawing;

public enum PixelFormat
{
    Format32bppArgb,
}

public enum ImageLockMode
{
    ReadOnly,
}

public struct Rectangle
{
    public Rectangle(int x, int y, int width, int height)
    {
        X = x;
        Y = y;
        Width = width;
        Height = height;
    }

    public int X { get; }
    public int Y { get; }
    public int Width { get; }
    public int Height { get; }
}

public sealed class BitmapData : IDisposable
{
    private nint _scan0;
    private bool _disposed;

    public nint Scan0 => _scan0;
    public int Stride { get; init; }
    public int Height { get; init; }

    public bool DisposeFreesScan0 { get; init; } = true;

    public void Dispose()
    {
        if (!_disposed && DisposeFreesScan0 && _scan0 != nint.Zero)
        {
            Marshal.FreeHGlobal(_scan0);
        }
        _disposed = true;
        _scan0 = nint.Zero;
    }
}

public sealed class Bitmap : IDisposable
{
    private readonly byte[] _bgra;   // BGRA bytes, row-major
    private nint? _scan0;
    private bool _disposed;

    public Bitmap(byte[] bgra, int width, int height)
    {
        _bgra = bgra;
        Width = width;
        Height = height;
    }

    public int Width { get; }
    public int Height { get; }

    public BitmapData LockBits(Rectangle rect, ImageLockMode mode, PixelFormat format)
    {
        // Return a pinned copy of the pixel buffer so the real Marshal.Copy path in VideoRecorderService runs.
        nint scan0 = Marshal.AllocHGlobal(_bgra.Length);
        Marshal.Copy(_bgra, 0, scan0, _bgra.Length);
        _scan0 = scan0;
        return new BitmapData { Scan0 = scan0, Stride = Width * 4, Height = Height };
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            _disposed = true;
            _scan0 = null;
        }
    }
}

namespace System.Windows.Forms.UITests;

public static class ScreenshotService
{
    private static readonly Queue<Func<Bitmap?>> s_screens = new();
    private static Func<Bitmap?>? s_last;
    private static readonly object Gate = new();

    public static void Reset() { lock (Gate) { s_screens.Clear(); s_last = null; } }

    // When the queue is emptied the last "screen" keeps being returned.
    public static void Enqueue(Bitmap? screen)
    {
        lock (Gate)
        {
            s_last = () => screen;
            s_screens.Enqueue(() => screen);
        }
    }

    public static Bitmap? TryCaptureFullScreen_Stub() => TryCaptureFullScreen();

    internal static Bitmap? TryCaptureFullScreen()
    {
        lock (Gate)
        {
            Func<Bitmap?>? next = s_screens.Count > 0 ? s_screens.Dequeue() : s_last;
            return next?.Invoke() is { } bitmap ? Clone(bitmap) : null;
        }
    }

    private static Bitmap Clone(Bitmap bitmap)
    {
        // The fake screen can be shared; hand each caller its own instance so disposal in the recorder is safe.
        return new Bitmap(bitmap.s_pixels, bitmap.Width, bitmap.Height);
    }
}

public static class DataCollectionService
{
    public static string CreateLogFileName(string extension, string errorId)
    {
        string dir = Environment.GetEnvironmentVariable("XUNIT_LOGS") switch
        {
            { Length: > 0 } baseDir => Path.Combine(baseDir, "Screenshots"),
            _ => Path.Combine(Path.GetTempPath(), "Screenshots"),
        };
        string sanitizedTestName = "TestHarness";
        string sanitizedErrorId = new string(errorId.Select(c => char.IsLetterOrDigit(c) ? c : '_').ToArray());
        return Path.Combine(dir, $"{DateTimeOffset.UtcNow:HH.mm.ss}-{sanitizedTestName}-{sanitizedErrorId}.{extension}");
    }
}

