// Behavioral validation of the real VideoRecorderService.cs + ApngWriter.cs with a controllable fake screen.
using System.IO.Compression;
using System.Text;
using System.Windows.Forms.UITests;

using namespace_unused = System.Drawing; // placeholder removed below

static class Program
{
    static int Checks, Failed;
    static void Check(bool c, string n) { Checks++; if (!c) { Failed++; Console.WriteLine($"  FAIL: {n}"); } }

    static void Main()
    {
        string logs = Path.Combine(Path.GetTempPath(), "recorder-logs-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(logs);
        Environment.SetEnvironmentVariable("XUNIT_LOGS", logs);

        ScenarioStaticScreen(logs);
        ScenarioMiddleBandChange(logs);
        ScenarioSuccessDiscards(logs);
        ScenarioFullScreenChange(logs);

        Console.WriteLine($"Total: {Checks} checks, {Failed} failures.");
        Environment.Exit(Failed == 0 ? 0 : 1);
    }

    static byte[] MakeBgra(int w, int h, byte r, byte g, byte b)
    {
        // Stored in memory as BGRA, like System.Drawing 32bppArgb.
        byte[] px = new byte[w * h * 4];
        for (int i = 0; i < px.Length; i += 4)
        {
            px[i] = b;
            px[i + 1] = g;
            px[i + 2] = r;
            px[i + 3] = 0xFF;
        }
        return px;
    }

    static void ScenarioStaticScreen(string logs)
    {
        ScreenshotService.Reset();
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(64, 48, 255, 0, 0), 64, 48));

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-static"));

        string? file = LatestApng(logs);
        Check(file is not null, "static: APNG written on failure");
        if (file is null) return;

        List<Frame> frames = ParseAndVerify(logs, file, expectFrames: 1);
        if (frames.Count == 1)
        {
            Check(frames[0].YOffset == 0 && frames[0].FrameHeight == 48, "static: single full height frame at y=0");
            byte[] dec = Inflate(frames[0].Data.ToArray());
            Check(dec.Length == 48 * (1 + 64 * 4), $"static: decompressed length {dec.Length}");
            bool rowsOk = true;
            for (int y = 0; y < 48 && rowsOk; y++)
            {
                rowsOk = dec[y * (1 + 256)] == 0;
                for (int x = 0; x < 64 && rowsOk; x++)
                {
                    int o = y * (1 + 256) + 1 + x * 4;
                    rowsOk = dec[o] == 255 && dec[o + 1] == 0 && dec[o + 2] == 0 && dec[o + 3] == 255; // RGBA
                }
            }
            Check(rowsOk, "static: pixels are the expected red screen");
        }
    }

    static void ScenarioMiddleBandChange(string logs)
    {
        ScreenshotService.Reset();
        int w = 64, h = 48;
        byte[] bgraA = MakeBgra(w, h, 255, 0, 0); // red screen
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(bgraA, w, h));

        ScreenshotService.Reset();
        // Re-enqueue A then B; Reset clears prior push.
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(bgraA, w, h));
        byte[] bgraB = MakeBgra(w, h, 255, 0, 0);
        for (int y = 10; y < 20; y++)
        {
            for (int x = 0; x < 64; x++)
            {
                int i = (y * w + x) * 4;
                bgraB[i] = 0xFF;     // B
                bgraB[i + 1] = 0xEE; // G
                bgraB[i + 2] = 0xCC; // R
            }
        }
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(bgraB, w, h));

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-band"));

        string? file = LatestApng(logs);
        Check(file is not null, "band: APNG written on failure");
        if (file is null) return;

        List<Frame> frames = ParseAndVerify(logs, file, expectFrames: 2);
        if (frames.Count == 2)
        {
            Check(frames[0].FrameHeight == 48 && frames[0].YOffset == 0, "band: frame 0 covers the full screen");
            Check(frames[1].YOffset == 10 && frames[1].FrameHeight == 10, $"band: frame 1 is the changed band only (y={frames[1].YOffset}, h={frames[1].FrameHeight})");
            byte[] dec = Inflate(frames[1].Data.ToArray());
            bool rowsOk = dec.Length == 10 * (1 + 256);
            for (int y = 0; y < 10 && rowsOk; y++)
            {
                rowsOk = dec[y * (1 + 256)] == 0;
                for (int x = 0; x < 64 && rowsOk; x++)
                {
                    int o = y * (1 + 256) + 1 + x * 4;
                    rowsOk = dec[o] == 0xCC && dec[o + 1] == 0xEE && dec[o + 2] == 0xFF;
                }
            }
            Check(rowsOk, "band: frame 1 pixels are the changed rows of the new screen");
        }
    }

    static void ScenarioSuccessDiscards(string logs)
    {
        ScreenshotService.Reset();
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(64, 48, 255, 0, 0), 64, 48));

        VideoRecorderService.StartRecording();
        Thread.Sleep(600);
        VideoRecorderService.StopRecording(failureException: null);   // success path

        Check(LatestApng(logs) is null, "success: no APNG is written when the test passes");
    }

    static void ScenarioFullScreenChange(string logs)
    {
        ScreenshotService.Reset();
        int w = 64, h = 48;
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(w, h, 255, 0, 0), w, h));
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(w, h, 0, 0, 255), w, h)); // full screen difference

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-full"));

        string? file = LatestApng(logs);
        Check(file is not null, "full: APNG written on failure");
        if (file is null) return;

        List<Frame> frames = ParseAndVerify(logs, file, expectFrames: 2);
        if (frames.Count == 2)
        {
            Check(frames[1].YOffset == 0 && frames[1].FrameHeight == 48, $"full: frame 1 covers the whole screen (y={frames[1].YOffset}, h={frames[1].FrameHeight})");
        }
    }

    // --- APNG verification ---

    static List<Frame> ParseAndVerify(string logs, string file, int expectFrames)
    {
        byte[] bytes = System.IO.File.ReadAllBytes(file);
        Check(bytes.Length > 0, "apng: file is not empty");

        List<(string Type, byte[] Data)> chunks = Parse(bytes);
        AfterScenario(logs);

        uint numFrames = 0;
        List<Frame> frames = new();
        Frame? current = null;
        foreach (var (type, data) in chunks)
        {
            switch (type)
            {
                case "acTL":
                    numFrames = ReadU32(data, 0);
                    break;
                case "fcTL":
                    current = new Frame
                    {
                        YOffset = ReadU32(data, 16),
                        FrameHeight = ReadU32(data, 8),
                        DelayNum = ReadU16(data, 20),
                    };
                    frames.Add(current);
                    break;
                case "IDAT":
                    current!.Data.AddRange(data);
                    break;
                case "fdAT":
                    current!.Data.AddRange(data[4..]);
                    break;
            }
        }

        Check(numFrames == expectFrames, $"apng: num_frames == {expectFrames} (got {numFrames})");
        Check(frames.Count == expectFrames, $"apng: fcTL count == {expectFrames}");
        foreach ((Frame f, int i) in frames.Select((f, i) => (f, i)))
        {
            Check(f.DelayNum >= 1 && f.DelayNum <= 3500, $"apng: frame {i} delay sane ({f.DelayNum}ms)");
        }
        return frames;
    }

