// Behavioral validation of the real VideoRecorderService.cs + ApngWriter.cs with a controllable fake screen.
using System.IO.Compression;
using System.Text;
using System.Windows.Forms.UITests;

static class Program
{
    static int Checks, Failed;
    static void Check(bool c, string n) { Checks++; if (!c) { Failed++; Console.WriteLine($"  FAIL: {n}"); } }

    static void Main()
    {
        string logs = Path.Combine(Path.GetTempPath(), "recorder-logs-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(logs);
        Environment.SetEnvironmentVariable("XUNIT_LOGS", logs);

        ScenarioStaticScreen(logs);
        ScenarioMiddleBandChange(logs);
        ScenarioFullScreenChange(logs);
        ScenarioSuccessDiscards(logs);

        Console.WriteLine($"Total: {Checks} checks, {Failed} failures.");
        Environment.Exit(Failed == 0 ? 0 : 1);
    }

    static byte[] MakeBgra(int w, int h, byte r, byte g, byte b)
    {
        // System.Drawing 32bppArgb stores pixels in memory as BGRA.
        byte[] px = new byte[w * h * 4];
        for (int i = 0; i < px.Length; i += 4)
        {
            px[i] = b;
            px[i + 1] = g;
            px[i + 2] = r;
            px[i + 3] = 0xFF;
        }
        return px;
    }

    static void ScenarioStaticScreen(string logs)
    {
        ScreenshotService.Reset();
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(64, 48, 255, 0, 0), 64, 48));

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-static"));

        string? file = LatestApng(logs);
        Check(file is not null, "static: APNG written on failure");
        if (file is null) return;

        List<AFrame> frames = ParseAndVerify(logs, file, expectFrames: 1);
        if (frames.Count == 1)
        {
            Check(frames[0].YOffset == 0 && frames[0].FrameHeight == 48, "static: single full height frame at y=0");
            byte[] dec = Inflate(frames[0].Data.ToArray());
            Check(dec.Length == 48 * (1 + 64 * 4), $"static: decompressed length {dec.Length}");
            bool rowsOk = true;
            for (int y = 0; y < 48 && rowsOk; y++)
            {
                rowsOk = dec[y * (1 + 256)] == 0;
                for (int x = 0; x < 64 && rowsOk; x++)
                {
                    int o = y * (1 + 256) + 1 + x * 4;
                    rowsOk = dec[o] == 255 && dec[o + 1] == 0 && dec[o + 2] == 0 && dec[o + 3] == 255; // RGBA
                }
            }
            Check(rowsOk, "static: pixels are the expected red screen");
        }
    }

    static void ScenarioMiddleBandChange(string logs)
    {
        ScreenshotService.Reset();
        int w = 64, h = 48;
        byte[] bgraA = MakeBgra(w, h, 255, 0, 0); // red screen
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(bgraA, w, h));

        byte[] bgraB = MakeBgra(w, h, 255, 0, 0);
        for (int y = 10; y < 20; y++)
        {
            for (int x = 0; x < 64; x++)
            {
                int i = (y * w + x) * 4;
                bgraB[i] = 0xFF;     // B differs only in rows 10..19
                bgraB[i + 1] = 0xEE; // G
                bgraB[i + 2] = 0xCC; // R
            }
        }
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(bgraB, w, h));

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-band"));

        string? file = LatestApng(logs);
        Check(file is not null, "band: APNG written on failure");
        if (file is null) return;

        List<AFrame> frames = ParseAndVerify(logs, file, expectFrames: 2);
        if (frames.Count == 2)
        {
            Check(frames[0].FrameHeight == 48 && frames[0].YOffset == 0, "band: frame 0 covers the full screen");
            Check(frames[1].YOffset == 10 && frames[1].FrameHeight == 10, $"band: frame 1 is the changed band only (y={frames[1].YOffset}, h={frames[1].FrameHeight})");
            byte[] dec = Inflate(frames[1].Data.ToArray());
            bool rowsOk = dec.Length == 10 * (1 + 256);
            for (int y = 0; y < 10 && rowsOk; y++)
            {
                rowsOk = dec[y * (1 + 256)] == 0;
                for (int x = 0; x < 64 && rowsOk; x++)
                {
                    int o = y * (1 + 256) + 1 + x * 4;
                    rowsOk = dec[o] == 0xCC && dec[o + 1] == 0xEE && dec[o + 2] == 0xFF;
                }
            }
            Check(rowsOk, "band: frame 1 pixels are the changed rows of the new screen");
        }
    }

    static void ScenarioFullScreenChange(string logs)
    {
        ScreenshotService.Reset();
        int w = 64, h = 48;
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(w, h, 255, 0, 0), w, h));
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(w, h, 0, 0, 255), w, h)); // full screen difference

        VideoRecorderService.StartRecording();
        Thread.Sleep(1200);
        VideoRecorderService.StopRecording(new InvalidOperationException("fail-full"));

        string? file = LatestApng(logs);
        Check(file is not null, "full: APNG written on failure");
        if (file is null) return;

        List<AFrame> frames = ParseAndVerify(logs, file, expectFrames: 2);
        if (frames.Count == 2)
        {
            Check(frames[1].YOffset == 0 && frames[1].FrameHeight == 48, "full: frame 1 covers the whole screen");
        }
    }

    static void ScenarioSuccessDiscards(string logs)
    {
        ScreenshotService.Reset();
        ScreenshotService.Enqueue(new System.Drawing.Bitmap(MakeBgra(64, 48, 255, 0, 0), 64, 48));

        VideoRecorderService.StartRecording();
        Thread.Sleep(600);
        VideoRecorderService.StopRecording(failureException: null);   // success path

        Check(LatestApng(logs) is null, "success: no APNG is written when the test passes");
    }

    // --- APNG verification ---

    static List<AFrame> ParseAndVerify(string logs, string file, int expectFrames)
    {
        byte[] bytes = File.ReadAllBytes(file);

        List<(string Type, byte[] Data)> chunks = Parse(bytes);
        Check(chunks[0].Type == "IHDR", "apng: first chunk is IHDR");
        Check(chunks[1].Type == "acTL", "apng: second chunk is acTL");

        uint numFrames = ReadU32(chunks[1].Data, 0);
        List<AFrame> frames = new();
        AFrame? current = null;
        foreach (var (type, data) in chunks)
        {
            switch (type)
            {
                case "fcTL":
                    current = new AFrame
                    {
                        YOffset = ReadU32(data, 16),
                        FrameHeight = ReadU32(data, 8),
                        DelayNum = ReadU16(data, 20),
                    };
                    frames.Add(current);
                    break;
                case "IDAT":
                    current!.Data.AddRange(data);
                    break;
                case "fdAT":
                    current!.Data.AddRange(data[4..]);
                    break;
            }
        }

        Check(numFrames == expectFrames, $"apng: num_frames == {expectFrames} (got {numFrames})");
        Check(frames.Count == expectFrames, $"apng: fcTL count == {expectFrames} (got {frames.Count})");
        for (int i = 0; i < frames.Count; i++)
        {
            Check(frames[i].DelayNum >= 1 && frames[i].DelayNum <= 3500, $"apng: frame {i} delay sane ({frames[i].DelayNum}ms)");
        }
        return frames;
    }

    static string? LatestApng(string logs)
    {
        DirectoryInfo dir = new(logs);
        if (!dir.Exists) return null;
        return dir.GetFiles("*.apng").OrderByDescending(f => f.LastWriteTimeUtc).FirstOrDefault()?.FullName;
    }

    static List<(string, byte[])> Parse(byte[] bytes)
    {
        List<(string, byte[])> chunks = new();
        int pos = 8;
        while (pos + 12 <= bytes.Length)
        {
            uint length = ReadU32(bytes, pos);
            pos += 4;
            string type = Encoding.ASCII.GetString(bytes, pos, 4);
            chunks.Add((type, bytes.AsSpan(pos + 4, (int)length).ToArray()));
            pos += (int)length + 8;
        }
        return chunks;
    }

    static byte[] Inflate(byte[] z)
    {
        using var i = new MemoryStream(z);
        using var zs = new ZLibStream(i, CompressionMode.Decompress);
        using var o = new MemoryStream();
        zs.CopyTo(o);
        return o.ToArray();
    }

    static uint ReadU32(ReadOnlySpan<byte> d, int o) => (uint)((d[o] << 24) | (d[o + 1] << 16) | (d[o + 2] << 8) | d[o + 3]);
    static ushort ReadU16(ReadOnlySpan<byte> d, int o) => (ushort)((d[o] << 8) | d[o + 1]);

    sealed class AFrame
    {
        public uint YOffset { get; init; }
        public uint FrameHeight { get; init; }
        public ushort DelayNum { get; init; }
        public List<byte> Data { get; } = new();
    }
}

// Minimal stand-ins that let the real VideoRecorderService.cs and ApngWriter.cs compile and run without
// System.Drawing.Common or the WinForms test infrastructure. System.Drawing.Rectangle comes from the inbox
// System.Drawing.Primitives assembly.

using System.Runtime.InteropServices;

namespace System.Drawing
{
    public sealed class Bitmap : IDisposable
    {
        public Bitmap(byte[] bgra, int width, int height)
        {
            Bgra = bgra;
            Width = width;
            Height = height;
        }

        internal byte[] Bgra { get; }

        public int Width { get; }
        public int Height { get; }

        public BitmapData LockBits(System.Drawing.Rectangle rect, System.Drawing.Imaging.ImageLockMode mode, System.Drawing.Imaging.PixelFormat format)
        {
            nint scan0 = Marshal.AllocHGlobal(Bgra.Length);
            Marshal.Copy(Bgra, 0, scan0, Bgra.Length);
            Scan0 = scan0;
            return new BitmapData { Scan0 = scan0, Stride = Width * 4, Height = Height };
        }

        internal nint? Scan0 { get; set; }

        public void Dispose()
        {
            Scan0 = null;
        }
    }
}

namespace System.Drawing.Imaging
{
    public enum PixelFormat
    {
        Format32bppArgb,
    }

    public enum ImageLockMode
    {
        ReadOnly,
    }

    public sealed class BitmapData : IDisposable
    {
        private nint _scan0;

        public nint Scan0 { get; init; }
        public int Stride { get; init; }
        public int Height { get; init; }

        public void Dispose()
        {
            if (_scan0 != nint.Zero)
            {
                Marshal.FreeHGlobal(_scan0);
                _scan0 = nint.Zero;
            }
        }
    }
}

namespace System.Windows.Forms.UITests
{
    public static class ScreenshotService
    {
        private static readonly Queue<Func<System.Drawing.Bitmap?>> s_screens = new();
        private static Func<System.Drawing.Bitmap?>? s_last;
        private static readonly object Gate = new();

        public static void Reset()
        {
            lock (Gate)
            {
                s_screens.Clear();
                s_last = null;
            }
        }

        // When the queue is emptied the last "screen" keeps being returned, so a static screen is easy to build.
        public static void Enqueue(System.Drawing.Bitmap? screen)
        {
            lock (Gate)
            {
                s_last = () => screen;
                s_screens.Enqueue(() => screen);
            }
        }

        internal static System.Drawing.Bitmap? TryCaptureFullScreen()
        {
            lock (Gate)
            {
                Func<System.Drawing.Bitmap?>? next = s_screens.Count > 0 ? s_screens.Dequeue() : s_last;
                return next?.Invoke() is { } bitmap ? Clone(bitmap) : null;
            }
        }

        private static System.Drawing.Bitmap Clone(System.Drawing.Bitmap source)
        {
            // Hand each caller its own instance so the recorder's disposal is safe.
            return new System.Drawing.Bitmap((byte[])source.Bgra.Clone(), source.Width, source.Height);
        }
    }

    public static class DataCollectionService
    {
        public static string CreateLogFileName(string extension, string errorId)
        {
            string dir = Environment.GetEnvironmentVariable("XUNIT_LOGS") switch
            {
                { Length: > 0 } baseDir => Path.Combine(baseDir, "Screenshots"),
                _ => Path.Combine(Path.GetTempPath(), "Screenshots"),
            };
            string sanitizedTestName = "TestHarness";
            string sanitizedErrorId = new string(errorId.Select(c => char.IsLetterOrDigit(c) ? c : '_').ToArray());
            return Path.Combine(dir, $"{DateTimeOffset.UtcNow:HH.mm.ss}-{sanitizedTestName}-{sanitizedErrorId}.{extension}");
        }
    }
}

