    /// <param name="errorId">The error ID, e.g. the name of the exception instance.</param>
    /// <returns>The fully qualified log file name.</returns>
    internal static string CreateLogFileName(string extension, string errorId)
    {
        return CreateLogFileName(GetLogDirectory(), DateTimeOffset.UtcNow, CurrentTestName, errorId, logId: string.Empty, extension);
    }

